13	  }
14	
15	  on(listener: Handler) {
16	    this.listeners.push(listener);
17	  }
18	
19	  private emit() {
20	    for (const l of this.listeners) l();
21	  }
22	
23	  add(label: string) {
24	    const trimmed = label.trim();
25	    if (!trimmed) return;
26	    this.tasks.push({ id: nextId(), label: trimmed, done: false, createdAt: Date.now() });
27	    this.persist();
28	  }
29	
30	  toggle(id: number) {
31	    const t = this.tasks.find((x) => x.id === id);
32	    if (t) t.done = !t.done;
33	    this.persist();
34	  }
35	
36	  remove(id: number) {
37	    this.tasks = this.tasks.filter((x) => x.id !== id);
38	    this.persist();
39	  }
40	
41	  clearCompleted() {
42	    this.tasks = this.tasks.filter((x) => !x.done);
43	    this.persist();
44	  }
45	
46	  countActive(): number {
47	    return this.tasks.filter((x) => !x.done).length;
48	  }
49	
50	  setFilter(filter: Filter) {
51	    this.filter = filter;
52	    saveFilter(filter);
53	    this.emit();
54	  }
55	
56	  getFilter() {
57	    return this.filter;
58	  }
59	
60	  // Returns tasks matching the current filter. Callers sometimes also
61	  // pass an explicit filter override (see todoFeature.ts), which is why
62	  // this isn't just a getter.
63	  getVisibleTasks(filterOverride?: Filter): Task[] {
64	    const f = filterOverride ?? this.filter;
65	    if (f === 'active') return this.tasks.filter((t) => !t.done);
66	    if (f === 'done') return this.tasks.filter((t) => t.done);
67	    return this.tasks;
68	  }
69	
70	  private persist() {
71	    saveTasks(this.tasks);
72	    this.emit();
73	  }
74	}

