export function renderSearchBox(current: string, onQueryChange: (query: string) => void): HTMLElement {
  const wrap = document.createElement('div');
  wrap.className = 'mb-5';

  const input = document.createElement('input');
  input.type = 'search';
  input.value = current;
  input.placeholder = 'Search tasks';
  input.setAttribute('aria-label', 'Search tasks');
  input.className = 'isks-input';
  input.addEventListener('input', () => onQueryChange(input.value));

  wrap.append(input);
  return wrap;
}

